"use strict";(self.webpackChunkgatsby_starter_default=self.webpackChunkgatsby_starter_default||[]).push([[463],{4023:function(e,t,a){a.r(t),a.d(t,{Head:function(){return l}});var n=a(7294),i=a(5592),o=a(9357);const l=()=>n.createElement(o.Z,{title:"Page two"});t.default=()=>n.createElement(i.Z,{workshop:"main"},n.createElement("h1",null,n.createElement("b",null,"Special issue on Journal of the European Mosquito Control Association (JEMCA)")),n.createElement("h2",null,"Advances in Modelling for Integrated Vector Control and Disease Risk Management"),n.createElement("p",null,"Vector-borne diseases (VBDs) represent a significant challenge to global public health, as they account for a substantial burden of morbidity and mortality worldwide. The dynamics of VBDs are complex, driven by interactions among vectors, hosts, pathogens, and the environment. Recent advances in mathematical modelling and machine learning techniques have revolutionised our ability to explore and predict these dynamics, offering innovative tools for understanding the spread, control, and potential elimination of these diseases. Dynamical modelling approaches, including compartmental models, stochastic simulations, and agent-based frameworks, have provided valuable insights into the transmission patterns of VBDs. Meanwhile, machine learning techniques, leveraging large datasets from surveillance systems, satellite observations, and genomic studies, have emerged as powerful complements to traditional models. Together, these tools enable researchers to capture non-linear interactions, assess spatial and temporal patterns, and predict disease risk with increasing accuracy."),n.createElement("p",null,'In this Special Issue dedicated to "Advances in modelling for integrated vector control and disease risk management", we call for cutting-edge, interdisciplinary contributions that focus on the application of mathematical modelling and machine learning to better understand and manage vectors and vector-borne diseases (V/VBD). Contributions are encouraged to address various aspects of vector distribution and dynamics, disease mechanisms and spread, and designing effective control strategies across diverse ecological and epidemiological contexts. We invite submissions related to, but not limited to, the following topics:'),n.createElement("p",null,n.createElement("ul",null,n.createElement("li",null,"Development and application of dynamical models (e.g., compartmental, stochastic, and agent-based models) to study V/VBD transmission.- Integration of environmental, behavioural, and genomic data into V/VBD models."),n.createElement("li",null,"Machine learning and artificial intelligence for predicting vector distribution and disease outbreaks. "),n.createElement("li",null,"Modelling the impact of climate change, land use, and urbanisation on V/VBD dynamics and transmission. "),n.createElement("li",null,"Novel methodologies for linking mathematical models with big data and ecoinformatics tools."),n.createElement("li",null,"Evaluation of control measures (e.g., vector management, vaccination, and treatment strategies) using dynamical models."),n.createElement("li",null,"Spatio-temporal analysis of V/VBD dynamics using advanced statistical or computational methods."))),n.createElement("p",null,"We encourage researchers from diverse fields, including epidemiology, ecology, mathematics, computer science, and public health, to contribute their work to this Special Issue. Authors with ideas for potential review articles or collaborative studies are invited to contact the Guest Editors to discuss the relevance and suitability of their topics."),n.createElement("p",null,"Detailed information about the submissions requirements are available ",n.createElement("a",{href:"https://brill.com/view/journals/jemc/jemc-overview.xml?language=en&contents=artsub"},"here"),". The deadline for the submissions of manuscripts is the ",n.createElement("b",null,"31st July 2025"),"."),n.createElement("p",null,"We look forward to your innovative and multidisciplinary contributions!"),n.createElement("p",null,"Dr. Daniele Da Re, Edmund Mach Foundation (Italy) ",n.createElement("a",{href:"mailto:daniele.dare@fmach.it"},"daniele.dare@fmach.it"),n.createElement("br",null),"Dr. Kamil Erguler, The Cyprus Institute (Cyprus) ",n.createElement("a",{href:"mailto:k.erguler@cyi.ac.cy"},"k.erguler@cyi.ac.cy")))}}]);
